// Generates simulated/abstract procedural dynamic "video" motion backgrounds to feel like a real scrolling feed
const VideoPlaceholder: React.FC<{ index: number; width: number; height: number; s: number }> = ({
  index,
  width,
  height,
  s,
}) => {
  const frame = useCurrentFrame();
  const seed = index * 100;

  // Derive stable pseudo-random properties based on index seed
  const numParticles = Math.floor(random(seed) * 5) + 5;
  const particleColor = random(seed + 1) > 0.5 ? "#00f0ff" : "#ff007f";
  const bgType = random(seed + 2) > 0.5 ? "gradient" : "grid";

  // Movement speed
  const speed = 1.8;

  return (
    <div
      style={{
        width,
        height,
        position: "absolute",
        top: 0,
        left: 0,
        background: bgType === "gradient" 
          ? `radial-gradient(circle at ${40 + random(seed + 3) * 20}% ${40 + random(seed + 4) * 20}%, #2e0854 0%, #0c021a 100%)`
          : "#09090b",
        display: "flex",
        flexDirection: "column",
        justifyContent: "flex-end",
        padding: 40 * s,
        boxSizing: "border-box",
      }}
    >
      {/* Background Graphic Grid */}
      {bgType === "grid" && (
        <div
          style={{
            position: "absolute",
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            opacity: 0.15,
            backgroundImage: "radial-gradient(circle, #ffffff 1px, transparent 1px)",
            backgroundSize: `${40 * s}px ${40 * s}px`,
          }}
        />
      )}

      {/* Randomized Moving Particles / Video Content Elements */}
      {Array.from({ length: numParticles }).map((_, i) => {
        const pSeed = seed + i * 15;
        const radius = (20 + random(pSeed) * 60) * s;
        const startX = random(pSeed + 1) * width;
        const startY = random(pSeed + 2) * height;
        
        // Constant slow drift motion
        const currentX = (startX + frame * speed * (random(pSeed + 3) > 0.5 ? 1 : -1)) % width;
        const currentY = (startY + frame * speed * (random(pSeed + 4) > 0.5 ? 1 : -1)) % height;

        return (
          <div
            key={i}
            style={{
              position: "absolute",
              left: currentX,
              top: currentY,
              width: radius * 2,
              height: radius * 2,
              borderRadius: "50%",
              backgroundColor: particleColor,
              opacity: 0.2 + random(pSeed + 5) * 0.3,
              filter: "blur(20px)",
              transform: "translate(-50%, -50%)",
            }}
          />
        );
      })}

      {/* Simulation of a dynamic UI track indicator to feel like a high energy dynamic post */}
      <div
        style={{
          position: "absolute",
          top: "40%",
          left: "50%",
          transform: "translate(-50%, -50%)",
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          gap: 16 * s,
        }}
      >
        <div
          style={{
            width: 120 * s,
            height: 120 * s,
            borderRadius: "50%",
            border: `${4 * s}px solid rgba(255, 255, 255, 0.4)`,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            boxShadow: "0 0 20px rgba(0,0,0,0.5)",
          }}
        >
          {/* Pulsing Play Button */}
          <svg
            width={48 * s}
            height={48 * s}
            viewBox="0 0 24 24"
            fill="white"
            style={{
              transform: `scale(${1 + Math.sin(frame * 0.1) * 0.08})`,
            }}
          >
            <polygon points="5 3 19 12 5 21 5 3" />
          </svg>
        </div>
        <span
          style={{
            color: "rgba(255, 255, 255, 0.8)",
            fontSize: 24 * s,
            fontWeight: 600,
            letterSpacing: 1.5,
            textTransform: "uppercase",
            textShadow: "0 2px 8px rgba(0,0,0,0.8)",
          }}
        >
          Live Video
        </span>
      </div>

      {/* Video Caption & Metadata Overlay bottom-left */}
      <div
        style={{
          position: "relative",
          zIndex: 5,
          color: "white",
          maxWidth: "80%",
          textShadow: "0 2px 4px rgba(0,0,0,0.6)",
        }}
      >
        <div style={{ display: "flex", alignItems: "center", gap: 12 * s, marginBottom: 12 * s }}>
          <div
            style={{
              width: 54 * s,
              height: 54 * s,
              borderRadius: "50%",
              backgroundColor: particleColor,
              border: `${2 * s}px solid white`,
            }}
          />
          <span style={{ fontWeight: 700, fontSize: 30 * s }}>@creator_node</span>
        </div>
        <p style={{ margin: 0, fontSize: 24 * s, lineHeight: 1.3, opacity: 0.9 }}>
          Catching the flow state. Dynamic simulated viewport render! #motion #interactive
        </p>
      </div>
    </div>
  );
};